@php($certificates = app(\App\Services\SiteRepository::class)->certificates())
<section class="certificates-section section-space"><div class="container-wide"><div class="certificates-grid">@foreach ($certificates as $index => $certificate)@php($n = $index + 1)<button aria-label="{{ __('site.view_certificate_n', ['n' => $n]) }}" class="certificate-card reveal" data-certificate="{{ media_url($certificate->image) }}" @if($certificate->file) data-certificate-file="{{ media_url($certificate->file) }}" @endif type="button"><span class="certificate-paper"><img alt="{{ $certificate->title ?: __('site.certificate_n', ['n' => $n]) }}" height="1100" loading="lazy" src="{{ media_url($certificate->image) }}" width="800"/></span><span class="certificate-caption"><span class="certificate-number">{{ str_pad($n, 2, '0', STR_PAD_LEFT) }}</span><span>{{ filled($certificate->title) ? $certificate->title : tval($data['view_text']) }}</span><span aria-hidden="true"><x-site.arrow /></span></span></button>@endforeach</div></div></section><dialog aria-label="{{ __('site.certificate_viewer') }}" class="certificate-dialog"><button aria-label="{{ __('site.close') }}" class="certificate-close" type="button">×</button><img alt="{{ __('site.certificate_viewer') }}" height="1100" src="data:image/gif;base64,R0lGODlhAQABAAAAACw=" width="800"/></dialog>
